"""Evaluation helpers; called only after scores exist (R9, R10)."""
import numpy as np
from sklearn.metrics import (roc_auc_score, average_precision_score,
                             precision_recall_curve)


def evaluate_scores(scores, y):
    """R9: AUC-ROC and AUC-PR (average precision primary, trapezoidal
    secondary)."""
    roc = float(roc_auc_score(y, scores))
    ap = float(average_precision_score(y, scores))
    prec, rec, _ = precision_recall_curve(y, scores)
    trap = float(np.trapezoid(prec[::-1], rec[::-1]))
    return {"auc_roc": roc, "auc_pr": ap, "auc_pr_trapezoid": trap}


def summarize(values):
    v = np.asarray(values, dtype=float)
    return {"mean": float(v.mean()), "std": float(v.std(ddof=0)),
            "min": float(v.min()), "max": float(v.max()),
            "values": [float(x) for x in v]}

